/* cppi::c9af519ac4b0ef0940fee3ed8370f0310a476bad568b1b8b8792c4e4aa877fe2 */
SELECT * FROM ci_etl_db_dev.ci_capital_pipeline_dealcloud_transformed
                WHERE CAST(extract_timestamp AS TIMESTAMP) = TIMESTAMP '2025-06-20 10:52:42'

/* cppi::b2143e7441fc4a45ffcf0d4dc5d3f702265a8ad4df9947a2be45a444bb58b356 */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-04-01'
    ) a
where last_publish = max_publish

/* cppi::a5d05c10f15f9a16277b800a4ac90bcadf9ed1e77b397d03ba9e1c9337cae671 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-14' and end_date = '2025-04-14')
and start_date = '2025-04-14' and end_date = '2025-04-14'

/* cppi::eceb8685ebc4d4f8b3b34f327842569d7a336c57a1b08eb1f9203e42399d6dba */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-01-02'
    ) a
where last_publish = max_publish

