/* cppi::80e50688c708aeb99a3cd4471002416b2cc8496e1cc69fc39b2b07e7a50453cb */
select business_date as date_, security_id, 'JPR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-19' and business_date <= date '2025-06-19' and weight_ndo>0 and id_cppib_index = 'JPR_GR_USD_0_0' and security_id is not null

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
-- Athena JDBC driver connection test
SELECT 1

/* cppi::e2c0be582ea6ca6eba1834ee4069dd4ab825740450bbe1b95220b38bfeb159d5 */
select * from market.cppib_index
where index_description LIKE 'FTSE EPRA NERIT Index%'

